1	// Red-first fixtures for the laugh-counter checks: each rule must fire on a
2	// violating file and stay quiet on the repo's real, clean ones. Run directly:
3	//
4	//   node --test .claudinite/local/packs/laugh-counter/pack.test.mjs
5	//
6	// They live here rather than in tests/ (`claudinite-isolation`). The fake ctx is
7	// the slice of the engine's context a check actually uses — `files`, `tracked`
8	// and `read` — so no git checkout is needed.
9	//
10	// Five of these rules are DECLARATIONS (declared-checks.json), so their half of
11	// the file compiles them through the mounted engine and needs `.claudinite/shared/`
12	// present; the three coded rules are imported directly.
13	import { test } from 'node:test';
14	import assert from 'node:assert/strict';
15	import { readFileSync } from 'node:fs';
16	import { dirname, join } from 'node:path';
17	import { fileURLToPath } from 'node:url';
18	
19	import inputNodeConfined from './input-node-confined.mjs';
20	import onDeviceSpeech from './on-device-speech.mjs';
21	import singleStorageDirectory from './single-storage-directory.mjs';
22	import { loadDeclaredChecks } from '../../../shared/engine/checks/helpers/pattern-rules.mjs';
23	
24	const here = dirname(fileURLToPath(import.meta.url));
25	const repoRoot = dirname(dirname(dirname(dirname(here))));
26	
27	const declared = (id) => {
28	  const rule = loadDeclaredChecks(here).find((r) => r.id === id);
29	  if (!rule) throw new Error(`no declared check ${id} in ${here}/declared-checks.json`);
30	  return rule;
31	};
32	const singleVersionSource = declared('laugh-counter/single-version-source');
33	const engineConstructionConfined = declared('laugh-counter/engine-construction-confined');
34	const noNetworkClient = declared('laugh-counter/no-network-client');
35	const noAudioPersistence = declared('laugh-counter/no-audio-persistence');
